INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(290401, 'ruRU', 'С возвращением к Свету, друг. Тебе нужно обучение?', 'С возвращением к Свету, друг. Тебе нужно обучение?', 0),
(292197, 'ruRU', '', 'Прочь от меня, чудовище!', 0),
(292198, 'ruRU', '', 'Нет! Нет, нет, нет! Этого не может быть. Я лучше умру, чем стану Отрекшейся! \r\n\r\n<Испуганный паладин поднимает оружие, готовясь к атаке!>', 0),
(292201, 'ruRU', 'Свет – это маяк, сияющий для каждого. Чем я могу помочь тебе, $c?', 'Свет – это маяк, сияющий для каждого. Чем я могу помочь тебе, $c?', 0),
(292949, 'ruRU', 'Здравствуй, $n! Не думал$g::а; о том, чтобы освоить какую-нибудь профессию?\r\n\r\nЯ с радостью отвечу на любые вопросы или подскажу, где найти местных учителей.\r\n\r\nЕсли тебе все это кажется слишком сложным, не переживай! Ты всегда можешь вернуться сюда или заглянуть к учителям в столицах, чтобы начать свой путь в ремеслах в любое время.', 'Здравствуй, $n! Не думал$g::а; о том, чтобы освоить какую-нибудь профессию?\r\n\r\nЯ с радостью отвечу на любые вопросы или подскажу, где найти местных учителей.\r\n\r\nЕсли тебе все это кажется слишком сложным, не переживай! Ты всегда можешь вернуться сюда или заглянуть к учителям в столицах, чтобы начать свой путь в ремеслах в любое время.', 0),
(292959, 'ruRU', 'Я рад, что ты спросил!\r\n\r\nПрофессии – это навыки, связанные с созданием предметов, добычей ресурсов и выживанием. Их много, и у каждой свои уникальные преимущества и возможности для заработка. Хочешь разбогатеть, пополнить склад гильдии полезными вещами или просто получать удовольствие от снаряжения, сделанного своими руками, – для всего этого найдется своя профессия.\r\n\r\nРецепты можно изучить у учителей, таких как местные, и во множестве других мест Азерота. Выучив рецепт, ты сможешь создавать сколько угодно таких предметов, если, конечно, достанешь необходимые материалы.', 'Я рад, что ты спросил!\r\n\r\nПрофессии – это навыки, связанные с созданием предметов, добычей ресурсов и выживанием. Их много, и у каждой свои уникальные преимущества и возможности для заработка. Хочешь разбогатеть, пополнить склад гильдии полезными вещами или просто получать удовольствие от снаряжения, сделанного своими руками, – для всего этого найдется своя профессия.\r\n\r\nРецепты можно изучить у учителей, таких как местные, и во множестве других мест Азерота. Выучив рецепт, ты сможешь создавать сколько угодно таких предметов, если, конечно, достанешь необходимые материалы.', 0),
(292988, 'ruRU', 'Конечно! К какой профессии мне тебя направить?\r\n\r\nЯ отмечу на твоей карте местоположение выбранного тобой учителя поблизости. Помни, что в столицах ты найдешь учителей, которые смогут обучить тебя более полно.', 'Конечно! К какой профессии мне тебя направить?\r\n\r\nЯ отмечу на твоей карте местоположение выбранного тобой учителя поблизости. Помни, что в столицах ты найдешь учителей, которые смогут обучить тебя более полно.', 0),
(293818, 'ruRU', 'Хочешь научиться снимать шкуры с убитых зверей? Или тебе нужны новые инструменты?', 'Хочешь научиться снимать шкуры с убитых зверей? Или тебе нужны новые инструменты?', 0),
(316839, 'ruRU', 'Отличный выбор. Я отметил это место на твоей карте.', 'Отличный выбор. Я отметил это место на твоей карте.', 0),
(325030, 'ruRU', 'Чем могу помочь?', 'Чем могу помочь?', 0);
